using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
public partial class NewGameRuntime
{
 static string PolicyName(HousePolicy p)=>p switch{HousePolicy.Balanced=>"均衡",HousePolicy.Build=>"開発重視",HousePolicy.Conserve=>"蓄え優先",HousePolicy.Military=>"軍備重視",_=>"商業重視"};
 long administrationAnnual=300;WorksKind administrationPriority=WorksKind.Agriculture;bool administrationHarvest=true;
 readonly Dictionary<string,Button> administrationReviewButtons=new();
 internal void ReviewAdministrationPress(string key)=>administrationReviewButtons[key].EmitSignal(Button.SignalName.Pressed);
 void ShowStandingAdministration(){if(IsSaving||IsClockControlling)return;var(box,rev)=SocialWindow("奉行の経費・家の方針・月報");administrationReviewButtons.Clear();var w=Snapshot();var actor=Session.PlayerControl;var site=SocialWorld.Site(w,actor);if(site==null){{}return;}var castle=w.NewGame!.Start.Castles.SingleOrDefault(c=>c.Id==site.Value.Value);if(castle?.Faction is not {} ownerName){{}return;}var owner=new EntityId(ownerName);
 EntityId Nonce(string key)=>new("request:admin-ui/"+rev+"/"+key);
 void Button(string key,string title,Action act){var b=new Button{Text=title};box.AddChild(b);administrationReviewButtons[key]=b;b.Pressed+=()=>{if(IsSaving||IsClockControlling)return;CancelAdvancePrefetch();act();Refresh();ShowStandingAdministration();};}
 void Act(string key,string title,AdministrationInput input)=>Button(key,title,()=>{var result=Session.ManageAdministration(input,rev);message.Text=result.VisibleReason;});
 SocialText(box,"自分が認識した家の方針："+PolicyName(StandingAdministration.KnownPolicy(w,actor,owner))+"\n経費の条件書と方針書は、届いて本人が開いてから効きます。年始・朔日の評定も実際に集まって開きます。");
 foreach(var paper in StandingAdministration.Inbox(w,actor).Where(p=>!MessageFlow.Knows(w.Messaging,p.Id,actor.Value)))Button("open-paper",paper.Type=="report"?"届いた奉行の月報を開く":"届いた条件書・方針書を開く",()=>{var result=Session.Open(actor,new(paper.Id),rev);message.Text=result.VisibleReason;});
 foreach(var paper in StandingAdministration.KnownPapers(w,actor).Where(p=>p.Recipient==actor)){if(paper.Type=="report")SocialText(box,$"月報：{NewGameWorld.SiteName(paper.Site.Value)}／観測{paper.At/86400}日目\n家の米 {paper.HouseRice}kg・銭{paper.HouseCash}文・普請原本{paper.Projects.Length}件。被害（観測時点）：{paper.Damage}。現在の遠隔の真実を表すものではありません。");else if(paper.Type=="terms"&&!w.Administration!.Events.Any(e=>e.Input.Reference==paper.Source&&e.Input.Action is AdministrationAction.AcceptTerms or AdministrationAction.DeclineTerms)){var src=w.Administration!.Events.Single(e=>e.Input.Id==paper.Source);SocialText(box,$"年度枠：銭{src.Input.AnnualCoins}文／優先{WorksName(src.Input.Priority)}／収穫期の人手回避：{src.Input.AvoidHarvest}");Act("accept-terms","この経費と方針で引き受ける",new(Nonce("accept"),AdministrationAction.AcceptTerms,src.Input.Owner,src.Input.Site,paper.Sender,src.Input.Id));Act("decline-terms","条件を辞退する",new(Nonce("decline"),AdministrationAction.DeclineTerms,src.Input.Owner,src.Input.Site,paper.Sender,src.Input.Id));}}
 var grant=StandingAdministration.Grant(w,actor,site.Value,w.ElapsedSeconds,w.CommitSequence+1);if(grant!=null)SocialText(box,"自分の今年の経費残枠："+StandingAdministration.Remaining(w,actor,site.Value)+"文。家の実在庫と現地の働き手は別に確認します。");
 if(HouseSuccession.Head(w,owner)==actor){var budget=new SpinBox{MinValue=50,MaxValue=3000,Step=50,Value=administrationAnnual,Prefix="年度経費：",Suffix="文"};box.AddChild(budget);budget.ValueChanged+=v=>administrationAnnual=(long)v;var kinds=new[]{WorksKind.Agriculture,WorksKind.Commerce,WorksKind.Workshop,WorksKind.Pasture,WorksKind.Mine,WorksKind.Port};var priority=new OptionButton();foreach(var k in kinds)priority.AddItem(WorksName(k));priority.Select(Array.IndexOf(kinds,administrationPriority));box.AddChild(priority);priority.ItemSelected+=v=>administrationPriority=kinds[(int)v];var harvest=new CheckBox{Text="収穫期（9〜10月）は新しい普請に人手を取らない",ButtonPressed=administrationHarvest};box.AddChild(harvest);harvest.Toggled+=v=>administrationHarvest=v;foreach(var person in HouseholdCourt.Roster(w,actor,owner).Where(p=>p!=actor&&w.Offices.Any(o=>o.Subject==p&&o.Target==site.Value&&(o.Kind is "house-steward" or "house-castellan")&&o.From<=w.ElapsedSeconds&&w.ElapsedSeconds<o.Until))){Button("issue-terms","この年度枠と優先分野を奉行へ書状で示す",()=>{var result=Session.ManageAdministration(new(Nonce("terms"),AdministrationAction.IssueTerms,owner,site.Value,person,AnnualCoins:administrationAnnual,Priority:administrationPriority,AvoidHarvest:administrationHarvest),rev);message.Text=result.VisibleReason;});}
 var meeting=w.Court?.Events.LastOrDefault(e=>e.Actor==actor&&e.Input.Action==CourtAction.HoldCouncil&&e.Input.Owner==owner&&e.Place==site.Value&&e.At<=w.ElapsedSeconds&&w.ElapsedSeconds<=e.At+3600);if(meeting!=null)foreach(var policy in Enum.GetValues<HousePolicy>())Act("policy-"+policy,"評定の方針を「"+PolicyName(policy)+"」と定めて書状で知らせる",new(Nonce("policy-"+policy),AdministrationAction.SetPolicy,owner,site.Value,actor,meeting.Input.Id,Policy:policy));else {}}
 }
}
